import 'package:material_ui/material_ui.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../auth/presentation/auth_controller.dart';
final adminAuditProvider=FutureProvider.autoDispose((ref)async{final r=await ref.watch(apiClientProvider).dio.get<List<dynamic>>('/api/admin/audit-logs');return r.data!;});
class AdminAuditPage extends ConsumerWidget{const AdminAuditPage({super.key});@override Widget build(BuildContext context,WidgetRef ref){final s=ref.watch(adminAuditProvider);return Scaffold(appBar:AppBar(title:const Text('سجل العمليات')),body:s.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(_,_)=>const Center(child:Text('تعذر تحميل سجل العمليات.')),data:(items)=>items.isEmpty?const Center(child:Text('لا توجد عمليات مسجلة.')):ListView.builder(itemCount:items.length,itemBuilder:(_,i){final x=items[i] as Map<String,dynamic>;return ListTile(title:Text(x['action']?.toString()??'عملية'),subtitle:Text(x['createdAt']?.toString()??''));})));}}
